import {renderProgressControl} from './room-progress.mjs';
import {renderPma} from './pma.mjs';
import {supplementalSources} from './supplemental-sources.mjs';
import {createPlanFilters} from './plan-filters.mjs';
import {renderProtocolCritical} from './protocol-critical.mjs';
import {renderProtocolCatalog} from './protocol-catalog.mjs';
import {renderConstruction} from './construction-dashboard.mjs';
import {categories,distribution,matchesLayers,categoryColor,categoryAppearance,layerNames,auditRoom,UNKNOWN} from './layers.mjs';
import {nivel,archivo} from './level.mjs';
export function createWorkspace(ctx){
 const $=id=>document.getElementById(id),esc=ctx.esc;
 let module='map',workTab=nivel.id==='N-1'?'room-progress':'matrix',matrixFocus=null,filters={},active='walls',enabled=false,legendMinimized=false,colors={},page=0,sort='code',direction=1,quality=false;
 try{colors=JSON.parse(localStorage.getItem('atlas-layer-colors')||'{}');}catch{}
 const all=()=>ctx.rooms(),rows=()=>ctx.results().filter(r=>matchesLayers(r,filters));
 const swatch=(type,key)=>{const a=categoryAppearance(type,key,colors);return `background:${a.color}${a.pattern?' url('+a.pattern+') repeat':''};opacity:${a.opacity}`;};
 function label(type,key){if(type==='asepsis')return key===UNKNOWN?'Clasificación no determinada':'Asepsia '+key;if(['PAV','CIE','paint','walls'].includes(type)){const m=ctx.data().materials.find(m=>m.code===key);return key==='-'?'No aplica (−)':m?key+' · '+m.description:key;}return key;}
 function show(name){if(ctx.editing()){ctx.toast('Guarda o cancela el contorno antes de cambiar de módulo.');return;}if(name==='layers'){drawer.open();return;}if(name==='dashboard'){workTab='documentary';name='work';}if(name!=='map')drawer.close();module=name;document.body.dataset.module=name;$('workspacePanel').hidden=name==='map';document.body.classList.add('hideLeft','hideRight');document.querySelectorAll('button[data-module]').forEach(b=>{b.classList.toggle('active',b.dataset.module===name);b.setAttribute('aria-current',b.dataset.module===name?'page':'false');});if(name==='map'){ctx.redraw();return;}refresh();}
 function heading(title,subtitle){return `<div class="moduleHeading"><div><div class="section-label">HOSPITAL PROVINCIA CORDILLERA / ${esc(nivel.nombre.toUpperCase())}</div><h1>${title}</h1><p>${subtitle}</p></div><button data-go-map>Volver al plano ↗</button></div>`;}
 function graph(type,title){const items=distribution(rows(),type),max=Math.max(1,...items.map(v=>v[1]));return `<section class="chartCard"><div class="chartHeading"><h3>${title}</h3><span>${items.length} categorías</span></div><div class="chartRows">${items.map(([key,n])=>`<button class="distributionRow" data-category="${esc(key)}" data-kind="${type}" title="Pintar y localizar en el plano"><span>${esc(label(type,key))}</span><b>${n}</b><i><em style="width:${n/max*100}%;background:${categoryColor(type,key,colors)}"></em></i></button>`).join('')}</div></section>`;}
 function dashboard(){const r=rows(),valid=r.filter(r=>r.geometry_status==='Validado').length,docvalid=r.filter(r=>r.status==='Validado').length;return '<div class="documentaryIntro"><h2>Características del piso</h2><p>Atributos documentados de los recintos; no representan ejecución de obra. Selecciona una categoría para localizarla en el plano.</p></div>'+ `<div class="contextStrip"><span>Ámbito: ${esc(ctx.scope().name)}</span><span>${r.length} de ${all().length} recintos</span><button data-clear>Limpiar filtros</button></div><div class="kpiGrid">${[[r.length,'Recintos en la consulta',all().length+' identificados en el área'],[valid,'Contornos técnicos validados',r.length-valid+' pendientes de validación'],[docvalid,'Fichas validadas',r.length-docvalid+' por revisar'],[(r.length?valid/r.length*100:0).toFixed(1)+'%','Avance de contornos','Validación técnica, no cobertura de clic']].map(([n,t,s])=>`<article class="kpi"><span>${t}</span><b>${n}</b><small>${s}</small></article>`).join('')}</div><div class="chartGrid">${graph('liberacion','Liberación de frentes')}${graph('asepsis','Asepsia documentada')}${graph('PAV','Tipos de pavimento')}${graph('paint','Pinturas de muro')}${graph('CIE','Terminaciones de cielo')}${graph('walls','Terminaciones de muros')}${graph('sector','Recintos por sector')}</div><p class="dataNote">Una habitación puede tener varias terminaciones; por eso algunas distribuciones no son excluyentes. Las superficies auxiliares de consulta no certifican contornos técnicos.</p>`;}
 function table(){let r=rows();if(quality)r=r.filter(v=>auditRoom(v,ctx.hasGeometry(v.id)).length);r=[...r].sort((a,b)=>String(a[sort]||'').localeCompare(String(b[sort]||''),'es',{numeric:true})*direction);const pages=Math.max(1,Math.ceil(r.length/30));page=Math.min(page,pages-1);const finish=(r,t)=>r.finishes.filter(f=>t==='walls'?/^M/.test(f.field):t==='paint'?/^M/.test(f.field)&&/pintura|esmalte/i.test(f.description):f.field===t).map(f=>f.code+' · '+f.description).filter((v,i,a)=>a.indexOf(v)===i).join(' / ')||'Pendiente';return heading('Gestión de recintos','Tabla maestra vinculada al plano. Pulsa el código para localizar y editar la ficha.')+`<div class="tableActions"><span>${r.length} registros</span><label class="check"><input id="qualityOnly" type="checkbox" ${quality?'checked':''}> Solo con pendientes de calidad</label><button id="exportRows">Exportar Excel</button><button id="exportCSV">CSV</button><button id="exportGeometry">Geometrías JSON</button><button id="tableBackups">Respaldos</button></div><div class="tableScroll"><table class="masterTable"><thead><tr>${[['code','Código'],['name','Nombre'],['level','Nivel'],['sector','Sector'],['status','Estado']].map(([k,t])=>`<th><button data-sort="${k}">${t} ${sort===k?(direction===1?'↑':'↓'):'↕'}</button></th>`).join('')}<th>Pavimento</th><th>Pintura</th><th>Muros</th><th>Cielo</th><th>Asepsia</th><th>Fuente / revisión</th><th>Control de calidad</th></tr></thead><tbody>${r.slice(page*30,(page+1)*30).map(v=>{const d=ctx.data().documents.find(d=>d.id===v.document_id);return `<tr class="${ctx.selected()?.id===v.id?'selectedRow':''}"><td><button class="codeLink" data-room="${esc(v.id)}">${esc(v.code)}</button></td><td>${esc(v.name)}</td><td>${esc(v.level)}</td><td>${esc(v.sector)}</td><td><span class="status ${v.status==='Validado'?'valid':''}">${esc(v.status)}</span></td><td>${esc(finish(v,'PAV'))}</td><td>${esc(finish(v,'paint'))}</td><td>${esc(finish(v,'walls'))}</td><td>${esc(finish(v,'CIE'))}</td><td>${esc(v.asepsis.join(', ')||UNKNOWN)}</td><td>${esc(d.code)}<br>${esc(d.revision||UNKNOWN)}</td><td>${esc(auditRoom(v,ctx.hasGeometry(v.id)).join(' · ')||'Sin alertas automáticas')}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>Página ${page+1} de ${pages} · 30 por página</span><button id="prevPage" ${page===0?'disabled':''}>Anterior</button><button id="nextPage" ${page+1===pages?'disabled':''}>Siguiente</button></div>`;}
 function docs(){const list=ctx.data().documents;return heading('Documentación y fuentes',`Los ${list.length} originales se conservan íntegros. Cada ficha mantiene su referencia documental.`)+`<div class="documentGrid">${list.map(d=>`<article class="chartCard"><span class="section-label">SECTOR ${esc(d.sector)} / ${esc(nivel.nombre.toUpperCase())}</span><h3>${esc(d.code)}</h3><p>${esc(d.metadata.source_original_name)}</p><small>Revisión ${esc(d.revision||UNKNOWN)} · ${d.kind==='dwg'?'DWG · SHA256 '+esc(d.sha256||UNKNOWN):'Página 1'}</small><div class="actions"><a class="sourceLink" href="source/${encodeURIComponent(d.filename)}" target="_blank" rel="noopener">${d.kind==='dwg'?'Planta en PDF':'Abrir PDF'} ↗</a>${d.legend===null?'':`<button data-doc="${esc(d.id)}">Ver simbología</button>`}</div></article>`).join('')}</div><h2>Fuentes complementarias</h2><div class="documentGrid">${supplementalSources.map(d=>`<article class="chartCard"><h3>${esc(d.title)}</h3><p>${esc(d.note)}</p><small>Revisión: ${esc(d.revision)} · página ${d.page}<br>SHA256 ${esc(d.sha256)}</small><p><a class="sourceLink" href="source/${esc(d.filename)}" target="_blank" rel="noopener">Abrir fuente de contraste ↗</a></p></article>`).join('')}</div><div class="hint">Para abrir los PDF sin señal, descárgalos desde «Sin conexión». El paquete de plano y fichas conserva los rombos y leyendas.</div>`;}
 function apply(type,key){ctx.architecture?.();active=type;enabled=true;filters[type]=[key];show('map');ctx.refresh();}
 function refresh(){if(module==='map'){drawer.update();return;}const root=$('workspacePanel');if(module==='work'){root.innerHTML=heading('Control de obra','Protocolos de la matriz, seguimiento y características documentadas del piso.')+`<nav class="workTabs" aria-label="Vista de control"><button data-work-tab="room-progress" aria-pressed="${workTab==='room-progress'}">Avance por recinto</button><button data-work-tab="matrix" aria-pressed="${workTab==='matrix'}">Protocolos de la matriz</button><button data-work-tab="critical" aria-pressed="${workTab==='critical'}">Protocolos críticos</button><button data-work-tab="pma" aria-pressed="${workTab==='pma'}">PMA de terminaciones</button><button data-work-tab="progress" aria-pressed="${workTab==='progress'}">Avances y protocolos</button><button data-work-tab="documentary" aria-pressed="${workTab==='documentary'}">Características del piso</button></nav><div id="workContent"></div>`;root.querySelectorAll('[data-work-tab]').forEach(b=>b.onclick=()=>{workTab=b.dataset.workTab;refresh();});root.querySelector('[data-go-map]').onclick=()=>show('map');if(workTab==='room-progress')renderProgressControl(root.querySelector('#workContent'),ctx);else if(workTab==='matrix'){const selection=matrixFocus;matrixFocus=null;renderProtocolCatalog(root.querySelector('#workContent'),ctx,{selection});}else if(workTab==='critical')renderProtocolCritical(root.querySelector('#workContent'),{...ctx,choose:selection=>{matrixFocus=selection;workTab='matrix';refresh();}});else if(workTab==='pma')renderPma(root.querySelector('#workContent'),{...ctx,locate:id=>{show('map');ctx.select(id);}});else if(workTab==='progress')renderConstruction(root.querySelector('#workContent'),ctx);else{root.querySelector('#workContent').innerHTML=dashboard();root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>apply(b.dataset.kind,b.dataset.category));root.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{clear();ctx.reset();refresh();});}return;}if(module==='liberacion'){root.innerHTML=ctx.liberacion.page(heading);ctx.liberacion.bindPage(root);root.querySelectorAll('[data-go-map]').forEach(b=>b.onclick=()=>show('map'));return;}root.innerHTML=module==='rooms'?table():docs();root.querySelectorAll('[data-go-map]').forEach(b=>b.onclick=()=>show('map'));root.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{clear();ctx.reset();refresh();});root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>apply(b.dataset.kind,b.dataset.category));root.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{show('map');ctx.select(b.dataset.room);});root.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:1;sort=b.dataset.sort;refresh();});root.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>ctx.modal(`<h2>Simbología original</h2><img style="width:100%" src="assets/${encodeURIComponent(b.dataset.doc)}/legend.png" alt="Leyenda documental">`));
 if(module==='rooms'){$('qualityOnly').onchange=e=>{quality=e.target.checked;page=0;refresh();};$('prevPage').onclick=()=>{page--;refresh();};$('nextPage').onclick=()=>{page++;refresh();};$('exportRows').onclick=()=>ctx.excel(quality?rows().filter(r=>auditRoom(r,ctx.hasGeometry(r.id)).length):rows());$('exportCSV').onclick=()=>exportCSV();$('exportGeometry').onclick=()=>exportGeometry();$('tableBackups').onclick=()=>$('import').click();}}
 function clear(){filters={};enabled=false;active='walls';page=0;}
 function appearance(r){if(!enabled||!matchesLayers(r,filters))return null;const keys=categories(r,active),key=keys.find(k=>(filters[active]||[]).includes(k))||keys[0];return categoryAppearance(active,key,colors);}
 function paint(r){return appearance(r)?.fill||null;}
 function legend(){
  const root=$('activeLegend'),hasFilters=Object.values(filters).some(v=>v.length);
  root.hidden=!enabled&&!hasFilters;if(root.hidden)return;
  root.classList.toggle('minimized',legendMinimized);
  const items=active==='selected'?[]:distribution(rows(),active).filter(([k])=>!filters[active]?.length||filters[active].includes(k));
  const activeNames=Object.entries(filters).filter(([,v])=>v.length).map(([k])=>layerNames[k]).join(', ');
  root.innerHTML=`<div class="legendHead"><strong>${esc(layerNames[active])}</strong><button id="minimizeLegend" aria-label="${legendMinimized?'Ampliar':'Minimizar'} leyenda" aria-expanded="${!legendMinimized}">${legendMinimized?'＋':'−'}</button></div><small id="activeFilterCount">${rows().length} recintos · ${hasFilters?'Filtros: '+esc(activeNames):'Sin filtro de categoría'}${enabled?'':' · colores apagados'}</small>${legendMinimized?'':`<div class="legendItems">${items.map(([k,n])=>`<div><i style="${swatch(active,k)}"></i><span>${esc(label(active,k))}</span><b>${n}</b></div>`).join('')}</div><div class="legendActions"><button id="togglePaint">${enabled?'Apagar':'Activar'} colores</button><button id="clearMapFilters">Limpiar filtros</button><button id="editLayers">Ajustar filtros</button></div><small id="legendColorNote">${active==='liberacion'?'Semáforo de liberación · opacidad 50%.':active==='CIE'?'Leyenda ARQ-CIE; colores modificados y sin muestra se indican en Filtros.':'Paleta de consulta · opacidad 32%.'} Trazo discontinuo: geometría pendiente.</small>`}`;
  $('minimizeLegend').onclick=()=>{legendMinimized=!legendMinimized;legend();};
  if(!legendMinimized){$('togglePaint').onclick=()=>{enabled=!enabled;ctx.redraw();};$('clearMapFilters').onclick=()=>{filters={};ctx.refresh();};$('editLayers').onclick=()=>show('layers');}
 }
 function exportCSV(){const r=rows().filter(r=>!quality||auditRoom(r,ctx.hasGeometry(r.id)).length);const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const fields=['Código','Nombre','Nivel','Sector','Estado','PAV','M1','M2','M3','M4','CIE','Asepsia','Fuente','Revisión'];const lines=r.map(v=>[v.code,v.name,v.level,v.sector,v.status,...['PAV','M1','M2','M3','M4','CIE'].map(k=>v.finishes.find(f=>f.field===k)?.description||UNKNOWN),v.asepsis.join(', '),v.document_id,ctx.data().documents.find(d=>d.id===v.document_id)?.revision]);ctx.download(new Blob(['\uFEFF'+[fields,...lines].map(a=>a.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),archivo('Atlas_HPC_recintos.csv'));}
 function exportGeometry(){ctx.download(new Blob([JSON.stringify({format:'atlas-hpc-selection-v1',coordinateSystem:'plano unificado; unidades PDF',warning:'Superficies de consulta; revisar estado técnico individual',rooms:rows().map(r=>({id:r.id,code:r.code,level:r.level,source:r.document_id,geometry_status:r.geometry_status,geometry:ctx.footprint(r.id)}))},null,2)],{type:'application/json'}),archivo('Atlas_HPC_geometrias.json'));}
 document.querySelectorAll('button[data-module]').forEach(b=>b.onclick=()=>show(b.dataset.module));$('sidebarCollapse').onclick=()=>document.body.classList.toggle('sidebarCompact');$('globalSearch').oninput=e=>{$('search').value=e.target.value;ctx.search();};$('globalSearch').onkeydown=e=>{if(e.key==='Enter'){show('map');document.body.classList.remove('hideLeft');ctx.search();}};
 window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('globalSearch').focus();}});
 function saveColors(){try{localStorage.setItem('atlas-layer-colors',JSON.stringify(colors));}catch{ctx.toast('No se pudo guardar la preferencia de color.');}}
 const drawer=createPlanFilters({esc,label,all,rows,state:()=>({active,filters,enabled,colors}),query:()=>$('globalSearch').value,editing:ctx.editing,toast:ctx.toast,resize:ctx.resize,enter:()=>{ctx.architecture?.();show('map');},search:value=>{$('globalSearch').value=value;$('search').value=value;ctx.search();},change:(value,search=true)=>{if(value.active)active=value.active;if('enabled' in value)enabled=value.enabled;if(search)ctx.refresh();else ctx.redraw();},filter:(type,keys)=>{filters[type]=keys;enabled=true;ctx.refresh();},color:(type,key,value)=>{colors[type+'|'+key]=value;saveColors();ctx.redraw();},resetColors:type=>{for(const key of Object.keys(colors))if(key.startsWith(type+'|'))delete colors[key];saveColors();ctx.redraw();},reset:ctx.reset});
 return {show,refresh,clear,rows,openFilters:drawer.open,closeFilters:drawer.close,filtersOpen:drawer.isOpen,paint,appearance,legend,setLayer:type=>{enabled=!!type;if(type)active=type;show('map');ctx.refresh();},filters:()=>filters,enabled:()=>enabled,apply};
}
